const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const upperArrowLake = ee.Geometry.Point([-118.2, 50.5]).buffer(5000);
  const date = '2018-10-22';

  // Morning (10:00-12:00 local time) - approx 17:00-19:00 UTC
  const morningStart = ee.Date(date).advance(17, 'hour');
  const morningEnd = ee.Date(date).advance(19, 'hour');

  // Afternoon (14:00-16:00 local time) - approx 21:00-23:00 UTC
  const afternoonStart = ee.Date(date).advance(21, 'hour');
  const afternoonEnd = ee.Date(date).advance(23, 'hour');

  // 2. Data Acquisition
  function getSentinel2Collection(startDate, endDate) {
    return ee.ImageCollection('COPERNICUS/S2')
      .filterBounds(upperArrowLake)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  const morningCol = getSentinel2Collection(morningStart, morningEnd);
  const afternoonCol = getSentinel2Collection(afternoonStart, afternoonEnd);

  // Check for empty collections
  const morningSize = morningCol.size().getInfo();
  const afternoonSize = afternoonCol.size().getInfo();

  console.log(`Morning images: ${morningSize}, Afternoon images: ${afternoonSize}`);

  if (morningSize === 0 || afternoonSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Cloud/fog detection using QA60 band
  function calculateCloudCoverage(image) {
    const qa = image.select('QA60');
    // Bit 10: Opaque clouds, Bit 11: Cirrus clouds
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;

    const clouds = qa.bitwiseAnd(cloudBitMask).gt(0)
                    .or(qa.bitwiseAnd(cirrusBitMask).gt(0));

    const stats = clouds.reduceRegion({
      reducer: ee.Reducer.frequencyHistogram(),
      geometry: upperArrowLake,
      scale: 1000,
      maxPixels: 1e9
    });

    return stats;
  }

  // Get first image from each collection
  const morningImg = morningCol.first();
  const afternoonImg = afternoonCol.first();

  const morningStats = calculateCloudCoverage(morningImg).getInfo();
  const afternoonStats = calculateCloudCoverage(afternoonImg).getInfo();

  // 4. Extract cloud percentages
  function getCloudPercentage(stats) {
    if (!stats || !stats['QA60']) return null;

    const hist = stats['QA60'];
    const total = (hist['0'] || 0) + (hist['1'] || 0);
    if (total === 0) return null;

    const cloudPixels = hist['1'] || 0;
    return (cloudPixels / total) * 100;
  }

  const morningCloud = getCloudPercentage(morningStats);
  const afternoonCloud = getCloudPercentage(afternoonStats);

  console.log(`Morning cloud %: ${morningCloud?.toFixed(1) || 'N/A'}`);
  console.log(`Afternoon cloud %: ${afternoonCloud?.toFixed(1) || 'N/A'}`);

  // 5. Validation & Final Answer
  if (morningCloud === null || afternoonCloud === null) {
    console.log("<answer>C2</answer>");
  } else if (isNaN(morningCloud) || isNaN(afternoonCloud)) {
    console.log("<answer>C3</answer>");
  } else if (afternoonCloud < morningCloud) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
